    if ((vector == NULL) || (axis == NULL) || (rotated == NULL)) {
        if (rotated != NULL) {
            rotated->x = 0.0;
            rotated->y = 0.0;
            rotated->z = 0.0;
        }
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(vector)) || (!adcs_is_finite_vec3(axis)) || (!isfinite(angle_rad))) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    adcs_vec3_t u;
    if (adcs_vec3_normalize(axis, ADCS_EPS_NORM, &u) != ADCS_OK) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    double cos_a = cos(angle_rad);
    double sin_a = sin(angle_rad);

    double dot_uv = adcs_vec3_dot(&u, vector);
    adcs_vec3_t cross_uv = adcs_vec3_cross(&u, vector);

    adcs_vec3_t term1 = adcs_vec3_scale(vector, cos_a);
    adcs_vec3_t term2 = adcs_vec3_scale(&cross_uv, sin_a);
    adcs_vec3_t term3 = adcs_vec3_scale(&u, dot_uv * (1.0 - cos_a));

    adcs_vec3_t result = adcs_vec3_add(&term1, &term2);
    result = adcs_vec3_add(&result, &term3);

    *rotated = result;
    return ADCS_OK;
}

